import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls} from './pathways-views.js?v=20261031-entry2';
import {heatmapSVG,quantumCurveSVG} from './quantum-plots.js?v=20261031-entry2';
export {esc,num,table,notes,sources,readControls};
const val=x=>typeof x==='boolean'?(x?'是':'否'):typeof x==='number'?num(x):x==null?'未定义':String(x);
const clean=r=>{const c=structuredClone(r);delete c.learningEvidence;return c;};
const anchors=new Map();
export function controlsHTML(m,v){const keys={statistics:[],defects:['separation','loopX','loopY','radius'],reciprocity:['field','magnetization','cross']}[m.id];return baseControls({...m,fields:m.fields.map(f=>f.type==='number'?{...f,step:'any'}:f)},v)+(keys.length?`<details><summary>连续调节参数</summary>${m.fields.filter(f=>keys.includes(f.key)).map(f=>`<label>${esc(f.label)}<input type="range" data-pr-control="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${v[f.key]}"></label>`).join('')}<p>修改后点击计算；缺陷图中可点击或拖动环路中心。</p></details>`:'');}
const matrix=m=>heatmapSVG(m[0].map((_,i)=>i),m.map((_,i)=>i),m,{title:'矩阵或向量（实部）',signed:true,xLabel:'列',yLabel:'行'});
export function plotHTML(p){
 if(p.kind==='response')return `<div class="cn-pair-grid"><div><h4>原配置 L</h4>${matrix(p.matrix)}</div><div><h4>反转配置 L</h4>${matrix(p.reversed)}</div></div>${table(['量','分量 1','分量 2'],[['共轭力',...p.force.map(num)],['响应流',...p.flux.map(num)]])}${table(['分解','第 1 行','第 2 行'],[['对称耗散部分',...p.symmetric.map(x=>x.map(num).join(', '))],['反对称部分',...p.antisymmetric.map(x=>x.map(num).join(', '))]])}`;
 if(p.kind==='ising')return `<svg viewBox="0 0 600 300" role="img" aria-label="Ising 畴壁的连续过零图"><path d="M40 150H560M300 25V270" stroke="#91a69b"/><polyline points="${p.x.map((x,i)=>`${300+65*x},${150-100*p.values[i]}`).join(' ')}" fill="none" stroke="#237c66" stroke-width="4"/><text x="45" y="280">x = −4</text><text x="480" y="280">x = 4</text><text x="320" y="35">序参量</text></svg>`;
 if(p.kind==='texture'){const xy=([x,y])=>[300+75*x,265-75*y];return `<svg id="cn-texture" viewBox="0 0 600 530" role="img" aria-label="方向场与闭合环路，可点击或拖动改变环路中心；也可用参数输入框"><rect x="65" y="30" width="470" height="470" fill="#f2f7f3"/>${p.field.map(([x,y,u,v])=>{const [a,b]=xy([x,y]),dx=10*u,dy=-10*v;return `<line x1="${a-dx}" y1="${b-dy}" x2="${a+dx}" y2="${b+dy}" stroke="#397c68" stroke-width="2"/>${p.headless?'':`<circle cx="${a+dx}" cy="${b+dy}" r="2.8" fill="#397c68"/>`}`;}).join('')}<polyline points="${p.path.map(q=>xy(q).join(',')).join(' ')}" fill="none" stroke="#b87631" stroke-width="4"/>${p.cores.map(([x,y,q])=>{const [a,b]=xy([x,y]);return `<circle cx="${a}" cy="${b}" r="9" fill="${q>0?'#b14b40':'#4464a1'}"/><text x="${a+12}" y="${b-10}">${q>0?'+':'−'}</text>`;}).join('')}<text x="65" y="525">−3 ≤ x,y ≤ 3 · 橙色为取样环路</text></svg>`;}
 if(p.kind==='amplitudes')return `<svg viewBox="0 0 680 330" role="img" aria-label="原态与操作后振幅，绿色原态、赭色操作后"><path d="M35 160H650" stroke="#a1b6aa"/>${p.labels.map((s,i)=>{const x=60+i*580/p.labels.length;return `<line x1="${x}" x2="${x}" y1="160" y2="${160-110*p.values[i]}" stroke="#237c66" stroke-width="9"/><line x1="${x+12}" x2="${x+12}" y1="160" y2="${160-110*p.after[i]}" stroke="#b87631" stroke-width="9"/><text x="${x}" y="300" text-anchor="middle">${esc(s)}</text>`;}).join('')}<text x="40" y="24">振幅 · 绿色原态 / 赭色操作后</text></svg>`;
 return '';
}
const tasks={projector:'非零反对称投影的归一化系数 c',young:'Y²=3Y：非零幂等归一化系数 c',exchange:'对称轨道 × 单重态的总交换符号',winding:'指向矢转过 π：Δθ/(2π)',onsager:'L12=a+b(B+M)，两偶变量的 L21',commutator:'[σz,hσx] 中 σy 的系数'};
export function resultHTML(module,r){return `<div class="cn-summary">${table(['本次结果','数值 / 诊断'],r.summary.map(s=>[s.label,val(s.value)]))}</div><section class="ct-panel"><h3>交互演示</h3>${plotHTML(r.plot)}</section><section class="ct-panel"><h3>推导与操作回放</h3><label>查看步骤<input id="cn-frame" type="range" min="0" max="${r.replay.length-1}" value="0" step="1"></label><div id="cn-frame-result"></div></section>${r.tables.map(t=>`<section class="ct-panel"><h3>${esc(t.title)}</h3>${table(t.headers,t.rows.map(row=>row.map(val)))}</section>`).join('')}<section class="ct-panel"><h3>公式与假设</h3>${r.formulas.map(f=>`<div class="obs-formula">${esc(f)}</div>`).join('')}${notes(r.notes)}</section><section class="ct-panel"><h3>反例挑战</h3><p>${esc(r.challenge.question)}</p>${r.challenge.choices.map((s,i)=>`<button type="button" class="secondary" data-cn-challenge="${i}">${esc(s)}</button>`).join('')}<p id="cn-challenge-feedback" role="status"></p></section><section class="ct-panel"><h3>带假设的符号步骤判分</h3><label>选择任务<select id="cn-task">${r.symbolicTasks.map(t=>`<option value="${t}">${tasks[t]}</option>`).join('')}</select></label><p>允许整数、括号、+ − * / 与 a b B M h I；用 1/2 表示分数，I 表示虚数单位。只核验本题指定恒等式。</p><label>你的精确表达式<input id="cn-answer" maxlength="180" placeholder="例如 1/2" autocomplete="off"></label><button id="cn-grade" type="button" class="secondary">检查这一步</button><div id="cn-grade-result" role="status"></div></section><section class="ct-panel"><h3>哈密顿量—状态—测量三层检查</h3><p>独立的二能级诊断台：H=hₓσₓ+h_zσ_z，ρ=(I+r n·σ)/2，探针在 xz 平面。它不自动替代上方模型。</p><div class="cn-audit-controls"><label>操作<select id="cn-operation"><option value="z">σz 幺正变换</option><option value="time">自旋 1/2 时间反演</option></select></label>${[['hx','hₓ',1,-2,2],['hz','h_z',0,-2,2],['stateAngle','态方向角（度）',0,-180,180],['probeAngle','探针角（度）',90,-180,180],['polarization','Bloch 向量长度 r',1,0,1]].map(([id,t,v,min,max])=>`<label>${t}<input id="cn-${id}" type="number" value="${v}" min="${min}" max="${max}" step="any"></label>`).join('')}</div><button id="cn-audit" type="button" class="secondary">分别检验三层对称性</button><div id="cn-audit-result" role="status"></div></section><section class="ct-panel"><h3>成对实验与证据报告</h3><p>先固定一次计算为 A，再修改参数得到 B。保存完整输入、结果和你的解释；记录不会自动发布。</p><div class="obs-links"><button id="cn-pin" type="button" class="secondary">将本次结果固定为 A</button><button id="cn-compare" type="button" class="secondary">与 A 比较并保存证据</button><button id="cn-clear" type="button" class="secondary">清除 A</button></div><label>本组比较的解释<textarea id="cn-explanation" rows="3" maxlength="6000" placeholder="反转了什么？哪些假设保持？数值支持什么结论？"></textarea></label><div id="cn-comparison" role="status"></div></section>`;}
export function bindResult(module,r,root,{runGrade,runAudit,input,isCurrent,onEvidence}){
 const $=s=>root.querySelector(s);let active=true,grading=0,auditing=0;
 const valid=()=>active&&isCurrent();
 const frame=()=>{const f=r.replay[+$('#cn-frame').value];$('#cn-frame-result').innerHTML=`<h4>${esc(f.title)}</h4><p>${esc(f.text)}</p>${f.matrix?matrix(f.matrix):''}`;};$('#cn-frame').oninput=frame;frame();
 const svg=$('#cn-texture');if(svg){svg.onpointerdown=e=>{svg.setPointerCapture?.(e.pointerId);};svg.onpointerup=e=>{const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const local=point.matrixTransform(svg.getScreenCTM().inverse());const x=Math.max(-3,Math.min(3,(local.x-300)/75)),y=Math.max(-3,Math.min(3,(265-local.y)/75));$('#pw-loopX').value=x.toFixed(3);$('#pw-loopY').value=y.toFixed(3);$('#pw-form').oninput({target:$('#pw-loopX')});$('#pw-form').onsubmit({preventDefault(){}});};}
 root.querySelectorAll('[data-cn-challenge]').forEach(b=>b.onclick=()=>{const answer=+b.dataset.cnChallenge,correct=answer===r.challenge.answer;$('#cn-challenge-feedback').textContent=(correct?'✓ ':'再想想：')+r.challenge.explanation;onEvidence('counterexample',{question:r.challenge.question,choice:r.challenge.choices[answer],correct,explanation:r.challenge.explanation});});
 const invalidateGrade=()=>{grading++;$('#cn-grade').disabled=false;$('#cn-grade-result').textContent='答案已改变，请重新检查。';onEvidence('symbolic',null);};$('#cn-task').onchange=invalidateGrade;$('#cn-answer').oninput=invalidateGrade;
 $('#cn-grade').onclick=async()=>{const id=++grading,payload={task:$('#cn-task').value,answer:$('#cn-answer').value};$('#cn-grade').disabled=true;try{const g=await runGrade(payload);if(!valid()||id!==grading)return;$('#cn-grade-result').innerHTML=`<p>${g.correct?'✓ 恒等式成立':'尚不相等'} · ${esc(g.prompt)}</p><p>差值：${esc(g.difference)}</p><p>${esc(g.hint)}</p>`;onEvidence('symbolic',{input:payload,result:g});}catch(e){if(valid()&&id===grading)$('#cn-grade-result').textContent=e.message;}finally{if(valid()&&id===grading)$('#cn-grade').disabled=false;}};
 const auditKeys=['hx','hz','stateAngle','probeAngle','polarization','operation'];
 for(const key of auditKeys)$('#cn-'+key).oninput=()=>{auditing++;$('#cn-audit').disabled=false;$('#cn-audit-result').textContent='诊断参数已改变，请重新检验。';onEvidence('audit',null);};
 $('#cn-audit').onclick=async()=>{const id=++auditing,payload=Object.fromEntries(auditKeys.map(k=>[k,k==='operation'?$('#cn-'+k).value:Number($('#cn-'+k).value)]));$('#cn-audit').disabled=true;try{const a=await runAudit(payload);if(!valid()||id!==auditing)return;$('#cn-audit-result').innerHTML=table(['检查','残差 / 结果'],[['操作',a.operation],['模型对称性残差',num(a.hamiltonian)],['态对称性残差',num(a.state)],['探针对称性残差',num(a.probe)],['探针为奇',val(a.probeOdd)],['期望值',num(a.expectation)],['由此对称性强制为零',val(a.forcedZero)]])+`<p>${esc(a.note)}</p>`;onEvidence('audit',{input:payload,result:a});}catch(e){if(valid()&&id===auditing)$('#cn-audit-result').textContent=e.message;}finally{if(valid()&&id===auditing)$('#cn-audit').disabled=false;}};
 const status=()=>{$('#cn-comparison').textContent=anchors.has(module)?'A 已固定，可修改主参数后计算 B。':'尚未固定 A。';};status();
 $('#cn-pin').onclick=()=>{anchors.set(module,{input:structuredClone(input),result:clean(r),created:new Date().toISOString()});onEvidence('comparison',null);status();};
 $('#cn-clear').onclick=()=>{anchors.delete(module);onEvidence('comparison',null);status();};
 const compare=()=>{const A=anchors.get(module);if(!A){status();return;}const B={input:structuredClone(input),result:clean(r),created:new Date().toISOString()},explanation=$('#cn-explanation').value;onEvidence('comparison',{A,B,explanation});$('#cn-comparison').innerHTML=table(['量','A','B'],r.summary.map(s=>[s.label,val(A.result.summary.find(x=>x.label===s.label)?.value),val(s.value)]))+`<p>完整 A/B 参数和结果已附在本次计算中，可导出 JSON 或收录到材料项目。解释${explanation.trim()?'已保存':'尚未填写'}。</p>`;};$('#cn-compare').onclick=compare;$('#cn-explanation').oninput=()=>{onEvidence('comparison',null);$('#cn-comparison').textContent='解释已修改，请重新点击比较以保存。';};
 return ()=>{active=false;grading++;auditing++;};
}
